#include "gba/genres/DeckbuilderModule.h"
#include "gba/genres/GenreUtil.h"
#include <algorithm>
#include <cmath>
#include <sstream>

namespace gba { using namespace genreutil;
std::string DeckbuilderModule::genre()const{return "deckbuilder";}
std::vector<ParameterSpec>DeckbuilderModule::balanceParameters(const GameDefinition&g)const{std::vector<ParameterSpec>p;for(const auto&c:arrayObjects(g.raw,"cards")){auto id=str(c,"id");p.push_back(spec("card."+id+".powerMul",1,.45,2.5,.18,false,"card"));p.push_back(spec("card."+id+".costMul",1,.55,1.8,.15,false,"card"));p.push_back(spec("card."+id+".drawMul",1,.5,2,.15,false,"card"));p.push_back(spec("card."+id+".synergyMul",1,.5,2.5,.18,false,"synergy"));}for(const auto&e:arrayObjects(g.raw,"enemies")){auto id=str(e,"id");p.push_back(spec("enemy."+id+".hpMul",1,.55,2.2,.17));p.push_back(spec("enemy."+id+".damageMul",1,.55,2.2,.17));p.push_back(spec("enemy."+id+".rewardMul",1,.6,1.8,.14));}p.push_back(spec("global.energyMul",1,.75,1.35,.12));p.push_back(spec("global.rewardMul",1,.65,1.5,.12));return p;}
std::vector<ParameterSpec>DeckbuilderModule::strategyParameters(const GameDefinition&g)const{std::vector<ParameterSpec>p;for(const auto&c:arrayObjects(g.raw,"cards")){p.push_back(spec("pref."+str(c,"id"),1,.02,4,.22));}p.push_back(spec("aggression",1,.2,2,.18));p.push_back(spec("defense",1,.2,2,.18));p.push_back(spec("comboBias",.8,0,2,.18));p.push_back(spec("shopGreed",.5,0,1.5,.18));return p;}
SimulationResult DeckbuilderModule::simulate(const GameDefinition&g,const Genome&b,const Genome&s,std::uint64_t seed,int maxP)const{std::mt19937_64 rng(seed);SimulationResult r;r.strategyId=s.id;r.balanceId=b.id;r.seed=seed;auto cards=arrayObjects(g.raw,"cards"),enemies=arrayObjects(g.raw,"enemies");auto rules=g.raw["rules"];double hp=attr(rules,"playerHp",80),startHp=hp,gold=attr(rules,"startGold",0),income=gold;std::map<std::string,double>deck;for(const auto&c:cards)if(attr(c,"starter",0)>0)deck[str(c,"id")]=attr(c,"starter",0);if(deck.empty()&&!cards.empty())deck[str(cards.front(),"id")]=5;double early=hp;for(int floor=1;floor<=maxP;++floor){const Json&e=enemies[static_cast<std::size_t>((floor-1)%std::max<int>(1,enemies.size()))];auto eid=str(e,"id","enemy");double enemyHp=attr(e,"hp",35)*gene(b,"enemy."+eid+".hpMul")*std::pow(1.035,floor);double enemyDmg=attr(e,"damage",7)*gene(b,"enemy."+eid+".damageMul")*(1+.018*floor);int turns=0;double block=0;
 while(enemyHp>0&&hp>0&&turns<20){turns++;double energy=attr(rules,"energy",3)*gene(b,"global.energyMul");block=0;std::vector<const Json*>order;for(const auto&c:cards)order.push_back(&c);std::sort(order.begin(),order.end(),[&](const Json*a,const Json*bj){return s.get("pref."+str(*a,"id"),1)>s.get("pref."+str(*bj,"id"),1);});for(const Json*cp:order){auto id=str(*cp,"id"),role=str(*cp,"role","attack");if(deck[id]<=0)continue;double cost=std::max(.25,attr(*cp,"cost",1)*gene(b,"card."+id+".costMul"));if(cost>energy)continue;double p=attr(*cp,"power",6)*gene(b,"card."+id+".powerMul")*gene(b,"card."+id+".synergyMul")*(1+.08*std::max(0.0,deck[id]-1));double pref=s.get("pref."+id,1);if(pref<.25&&rand01(rng)>.2)continue;energy-=cost;if(role=="block"||role=="defense"){double x=p*s.get("defense",1);block+=x;r.contribution[id]+=x*.7;}else if(role=="draw"){double x=p*.45*gene(b,"card."+id+".drawMul");enemyHp-=x;r.contribution[id]+=x;}else{double x=p*s.get("aggression",1);enemyHp-=x;r.contribution[id]+=x;}r.usage[id]+=1;if(energy<.25)break;}if(enemyHp>0){double taken=std::max(0.0,enemyDmg-block);hp-=taken;}}
 if(hp<=0){r.progress=floor;r.success=false;break;}double reward=attr(e,"reward",10)*gene(b,"enemy."+eid+".rewardMul")*gene(b,"global.rewardMul");gold+=reward;income+=reward; // shop: add a card weighted by preference
 if(floor%2==0&&!cards.empty()){const Json*best=&cards.front();double bestU=-1;for(const auto&c:cards){auto id=str(c,"id");double price=attr(c,"price",20);double u=s.get("pref."+id,1)*attr(c,"power",6)/std::max(1.0,price);if(u>bestU&&gold>=price){bestU=u;best=&c;}}auto id=str(*best,"id");double price=attr(*best,"price",20);if(gold>=price&&bestU>0){gold-=price;deck[id]+=1;r.usage[id+".buy"]+=1;}}
 if(floor==5) early=hp;
 r.progress=floor;
 }
r.success=r.progress>=maxP;r.earlySafety=clamp01(early/startHp);r.resourceIncome=std::max(1.0,income);r.resourceResidual=gold;r.score=r.progress*35+r.earlySafety*500+r.success*1200;return r;}
EvaluationSummary DeckbuilderModule::evaluateBalance(const GameDefinition&g,const Genome&b,const std::vector<SimulationResult>&runs)const{auto e=IGameModule::evaluateBalance(g,b,runs);double target=g.raw["targets"]["targetProgress"].asNumber(30);if(e.avgProgress<target*.7)e.fitness-=(target*.7-e.avgProgress)*55;e.fitness-=std::max(0.0,e.topShare-.45)*4500;e.fitness-=std::max(0.0,e.topPairShare-.72)*6000;e.fitness+=e.diversity*700;std::ostringstream o;o<<"Deck target="<<e.fitness<<" floor="<<e.avgProgress<<" top="<<e.topShare;e.explanation=o.str();return e;}
std::vector<Genome>DeckbuilderModule::targetedBalanceExperiments(const GameDefinition&g,const Genome&base,const EvaluationSummary&c,std::uint64_t&nid,int gen,std::mt19937_64&,double strength)const{std::vector<Genome>v;std::string hi,lo;double a=-1,z=1e99;for(const auto&x:arrayObjects(g.raw,"cards")){auto id=str(x,"id");double q=c.meanContribution.count(id)?c.meanContribution.at(id):0,u=c.meanUsage.count(id)?c.meanUsage.at(id):0;if(q>a){a=q;hi=id;}if(u<z){z=u;lo=id;}}if(!hi.empty()&&!lo.empty()&&hi!=lo){Genome n=base;n.id=nid++;n.generation=gen;n.note="anti-card-meta:"+hi+"->"+lo;n.genes["card."+hi+".powerMul"]*=1-strength*.3;n.genes["card."+lo+".powerMul"]*=1+strength*.3;n.genes["card."+lo+".synergyMul"]*=1+strength*.25;v.push_back(n);}return v;}
}
